func newCredentialsListCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "list",
		Short: "List credentials",
		Long:  "List the credentials in your account, of every kind, a page at a time.\n\nCredentials are returned oldest first. Each entry says what connection type it is for and\nwhere its secret lives; read the typed endpoint for that kind to see its other fields.",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			api, ctx, err := apiClient(cmd)
			if err != nil {
				return err
			}
			req := api.CredentialsAPI.ListCredentials(ctx)
			if changed(cmd, "cursor") {
				cursor, err := flagString(cmd, "cursor")
				if err != nil {
					return err
				}
				req = req.Cursor(cursor)
			}
			if changed(cmd, "limit") {
				limit, err := flagInt(cmd, "limit")
				if err != nil {
					return err
				}
				req = req.Limit(limit)
			}
			if changed(cmd, "with-count") {
				withCount, err := flagBool(cmd, "with-count")
				if err != nil {
					return err
				}
				req = req.WithCount(withCount)
			}
			if !changed(cmd, "cursor", "limit", "with-count") {
				return renderPages(cmd, []string{"id", "connection_type", "storage_type", "created_time"}, func(cursor string) (any, *http.Response, error) {
					r := req
					if cursor != "" {
						r = r.Cursor(cursor)
					}
					return r.Execute()
				})
			}
			out, resp, err := req.Execute()
			if err != nil {
				return apiErr(resp, err)
			}
			return renderPage(cmd, out, []string{"id", "connection_type", "storage_type", "created_time"})
		},
	}
	cmd.Flags().String("cursor", "", "Position to continue from, as returned in next_cursor by the previous page. Omit it to start from the first page. The value is opaque; do not build or modify one.")
	cmd.Flags().Int32("limit", 0, "Maximum number of items to return, between 1 and 100.")
	cmd.Flags().Bool("with-count", false, "Whether to also return the total number of items across every page, in count. Off by default: counting costs an extra query.")
	return cmd
}

